    """Materiales sin unidad: toman la que ya usan en sus BOMs, si es una sola."""
    from django.db.models import Count, Min
    BomDetalle = apps.get_model("produccion", "BomDetalle")
    Producto = apps.get_model("catalogo", "Producto")
    filas = (BomDetalle.objects.filter(componente__unidad_medida__isnull=True, componente__isnull=False)
             .values("componente_id").annotate(n=Count("unidad_id", distinct=True), u=Min("unidad_id")).filter(n=1))
